$ErrorActionPreference='Stop'
if($env:COMPUTERNAME -cne 'LocalBox-Client'){throw 'Wrong outer host'}
if([DateTimeOffset]::UtcNow -ge [DateTimeOffset]::Parse('2026-11-10T18:00:00+02:00')){throw 'Inert probe window closed'}
$b=[Text.Encoding]::UTF8.GetBytes($MyInvocation.MyCommand.ScriptBlock.ToString())
$h=[Security.Cryptography.SHA256]::Create()
try{$s=[BitConverter]::ToString($h.ComputeHash($b)).Replace('-','').ToLowerInvariant()}finally{$h.Dispose()}
@{status='inert-size-matched-transport-probe';computer=$env:COMPUTERNAME;pid=$PID;sourceBytes=$b.Length;sourceSha256=$s;mutationPerformed=$false;effectsRequested=$false;atUtc=[datetime]::UtcNow.ToString('o')}|ConvertTo-Json -Compress
